// native-module/index.js and index.d.ts are generated by `napi build`, which
// only sees the Rust compiled for the machine running it. A build on a Mac
// drops every Windows-only export (deliverClicksWithoutActivation,
// isImeKeyboardActive) and a build on Windows drops the macOS-only ones; it can
// also weaken a typed return to `Promise<unknown>`. The committed files must
// list both platforms, so this checks them against the Rust source instead of
// against whatever the last build produced.
//
// The app itself loads the .node binary directly (electron/audio/
// nativeModuleLoader.ts), so a gap here breaks the published contract and the
// types, not the running app; this keeps a regenerated file from being
// committed by accident.

import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../..');
const srcDir = path.join(root, 'native-module', 'src');
const read = (rel) => fs.readFileSync(path.join(root, rel), 'utf8');

function rustFiles(dir) {
  const out = [];
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) out.push(...rustFiles(p));
    else if (p.endsWith('.rs')) out.push(p);
  }
  return out;
}

const files = rustFiles(srcDir);
const sources = new Map(files.map((f) => [f, fs.readFileSync(f, 'utf8')]));
const allSource = [...sources.values()].join('\n');

// A file is compiled only when some `mod <stem>;` names it (lib.rs is the root).
function compiled(file) {
  const stem = path.basename(file, '.rs');
  if (stem === 'lib' || stem === 'mod') return true;
  return new RegExp(`\\bmod\\s+${stem}\\s*;`).test(allSource);
}

/** Top-level `#[napi] pub fn` names, camelCased as napi exports them. */
function napiFunctions() {
  const names = new Map();
  for (const [file, text] of sources) {
    if (!compiled(file)) continue;
    const lines = text.split('\n');
    for (let i = 0; i < lines.length; i++) {
      const m = lines[i].match(/^#\[napi(?:\((.*)\))?\]\s*$/);
      if (!m) continue;
      const jsName = (m[1] || '').match(/js_name\s*=\s*"([^"]+)"/)?.[1];
      for (let j = i + 1; j < Math.min(i + 12, lines.length); j++) {
        const line = lines[j];
        if (/^\s*(#\[|\/\/)/.test(line)) continue;
        const fn = line.match(/^pub (?:async )?fn (\w+)/);
        if (fn) names.set(jsName || fn[1].replace(/_([a-z0-9])/g, (_, c) => c.toUpperCase()), path.relative(root, file));
        break;
      }
    }
  }
  return names;
}

const indexJs = read('native-module/index.js');
const indexDts = read('native-module/index.d.ts');

test('every compiled #[napi] function is exported by index.js and declared in index.d.ts, on both platforms', () => {
  const fns = napiFunctions();
  assert.ok(fns.size >= 20, `expected the native module's functions, found ${fns.size}`);
  const missing = [];
  for (const [name, file] of fns) {
    if (!indexJs.includes(`module.exports.${name} = nativeBinding.${name}\n`)) missing.push(`index.js: ${name} (${file})`);
    if (!new RegExp(`export declare function ${name}\\(`).test(indexDts)) missing.push(`index.d.ts: ${name} (${file})`);
  }
  assert.deepEqual(missing, [], 'regenerated on one OS? restore the other platform\'s exports');
});

test('the Windows-only exports are present', () => {
  for (const name of ['deliverClicksWithoutActivation', 'isImeKeyboardActive']) {
    assert.match(indexJs, new RegExp(`module\\.exports\\.${name} = nativeBinding\\.${name}\\n`));
  }
  assert.match(indexDts, /export declare function deliverClicksWithoutActivation\(handle: Buffer\): boolean/);
  assert.match(indexDts, /export declare function isImeKeyboardActive\(\): boolean/);
});

test('AsyncTask functions keep their typed result, never Promise<unknown>', () => {
  // `fn x() -> AsyncTask<XTask>` with `type JsValue = Y` must be declared Promise<Y>.
  const tasks = new Map();
  for (const m of allSource.matchAll(/impl\s+(?:napi::)?Task\s+for\s+(\w+)\s*\{[^{}]*?type\s+JsValue\s*=\s*([^;]+);/g)) tasks.set(m[1], m[2].trim());
  const checked = [];
  for (const m of allSource.matchAll(/^pub fn (\w+)\([^)]*\)\s*->\s*(?:napi::bindgen_prelude::)?AsyncTask<(\w+)>/gm)) {
    const js = m[1].replace(/_([a-z0-9])/g, (_, c) => c.toUpperCase());
    const value = tasks.get(m[2]);
    // Only our own #[napi(object)] structs; String, bool and friends map to string/boolean.
    if (!value || !new RegExp(`pub struct ${value}\\b`).test(allSource)) continue;
    assert.match(indexDts, new RegExp(`export declare function ${js}\\([^)]*\\): Promise<${value}>`), `${js} should resolve to ${value}`);
    checked.push(js);
  }
  assert.ok(checked.includes('probeOutputRoutes'), `probeOutputRoutes not checked (checked: ${checked.join(', ')})`);
  assert.match(indexDts, /export interface OutputRouteProbe \{/);
});
